    void script(String sql)throws Exception{try(Connection c=source.getConnection()){ScriptUtils.executeSqlScript(c,new org.springframework.core.io.ByteArrayResource(sql.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}}
    void createLeaveTables()throws Exception{String original=Files.readString(root().resolve("sql/erp_oa_attendance_v2_20260820.sql"));for(String table:List.of("oa_attendance_leave_type","oa_attendance_leave_request","oa_attendance_leave_segment","oa_attendance_leave_attachment","oa_attendance_leave_approval_start_outbox","oa_attendance_correction_request","oa_attendance_schedule_segment_snapshot")){int from=original.indexOf("CREATE TABLE IF NOT EXISTS "+table+" (");int to=original.indexOf(";",from);script(original.substring(from,to+1));}}
