    AttendanceLeaveRequests.SaveDraft draft(String key,int day,String amount){var b=new AttendanceLeaveRequests.SaveDraft();b.clientRequestId=key;b.leaveTypeId=1L;b.startTime=LocalDateTime.of(2026,9,day,9,0);b.endTime=b.startTime.plusHours(8);b.requestedDays=amount==null?null:new BigDecimal(amount);b.reason="synthetic confirmed days";return b;}
    LeaveRequest save(String key,int day,String amount){return leaveService.saveDraft(draft(key,day,amount),10L);}
    LeaveRequest submit(LeaveRequest r){return leaveService.submit(r.leaveRequestId,r.rowVersion,10L);}
    LeaveRequest linked(LeaveRequest r){submit(r);ApprovalStartResponse a=new ApprovalStartResponse();a.setInstanceId(900L+r.leaveRequestId);a.setBusinessRound(1);a.setStatus("RUNNING");when(remote.start(any(),anyString())).thenReturn(R.ok(a));dispatcher.dispatchOneNow(outbox.selectByRound(r.leaveRequestId,1).outboxId);LeaveRequest result=leaveService.detail(r.leaveRequestId,10L);assertThat(result.status).isEqualTo("PENDING");return result;}
    ApprovalBusinessCallbackRequest command(LeaveRequest r,String action,String target,String key){var b=new ApprovalBusinessCallbackRequest();b.setBusinessCode("OA_ATTENDANCE_LEAVE");b.setBusinessId(r.leaveRequestId.toString());b.setInstanceId(r.approvalInstanceId);b.setBusinessRound(r.businessRound);b.setEventKey(key);b.setAction(action);b.setPayload("{\"targetStatus\":\""+target+"\"}");return b;}
    long units(String field){return jdbc.queryForObject("SELECT COALESCE(SUM("+field+"),0) FROM oa_attendance_leave_balance_bucket",Long.class);}
    @Test void explicitDaysPersistAndSubmitAutomaticallyGrantsThenReserves(){LeaveRequest r=save("days-confirmed-001",13,"1");assertThat(r.totalMinutes).isEqualTo(480);assertThat(r.quotaUnits).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_balance_bucket")).isZero();LeaveRequest sent=submit(r);assertThat(sent.quotaStatus).isEqualTo("RESERVED");assertThat(units("granted_units")).isEqualTo(840_000_000L);assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_quota_allocation")).isEqualTo(1);assertThat(count("oa_attendance_leave_approval_start_outbox")).isEqualTo(1);}
    @Test void sameCreateAndSubmitRetryDoNotDuplicateQuota(){var body=draft("create-retry-001",13,"1");LeaveRequest r=leaveService.saveDraft(body,10L);assertThat(leaveService.saveDraft(body,10L).leaveRequestId).isEqualTo(r.leaveRequestId);LeaveRequest sent=submit(r);leaveService.submit(r.leaveRequestId,999L,10L);assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_quota_event")).isEqualTo(1);assertThat(sent.status).isEqualTo("SUBMITTING");}
    @Test void insufficientQuotaRollsBackAllPartialAllocationsAndBusiness(){submit(save("enough-001",13,"1"));LeaveRequest second=save("too-much-001",14,"2");long ledger=count("oa_attendance_leave_balance_ledger");assertThatThrownBy(()->submit(second)).hasMessageContaining("可用额度不足");assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_quota_allocation")).isEqualTo(1);assertThat(count("oa_attendance_leave_balance_ledger")).isEqualTo(ledger);assertThat(leaveService.detail(second.leaveRequestId,10L).status).isEqualTo("DRAFT");}
    @Test void concurrentRequestsCannotSpendOneRemainingQuotaTwice()throws Exception{LeaveRequest one=save("concurrent-a-001",13,"2"),two=save("concurrent-b-001",14,"2");ExecutorService pool=Executors.newFixedThreadPool(2);int ok=0,fail=0;try{List<Future<?>> futures=List.of(pool.submit(()->{employee();try{return submit(one);}finally{logout();}}),pool.submit(()->{employee();try{return submit(two);}finally{logout();}}));for(Future<?> f:futures)try{f.get(20,TimeUnit.SECONDS);ok++;}catch(ExecutionException error){assertThat(error.getCause()).isInstanceOf(com.erp.common.core.exception.ServiceException.class);fail++;}}finally{pool.shutdownNow();}assertThat(ok).isEqualTo(1);assertThat(fail).isEqualTo(1);assertThat(units("reserved_units")).isEqualTo(840_000_000L);assertThat(count("oa_attendance_leave_quota_allocation")).isEqualTo(1);}
    @Test void actualCallbackConsumesAndRepeatedEventDoesNotRepeat(){LeaveRequest r=linked(save("approval-001",13,"1"));var c=command(r,"APPROVE","APPROVED","approved-event");assertThat(callbackService.apply(c).getAccepted()).isTrue();assertThat(callbackService.apply(c).getCode()).isEqualTo("IDEMPOTENT");assertThat(units("reserved_units")).isZero();assertThat(units("consumed_units")).isEqualTo(420_000_000L);assertThat(leaveService.detail(r.leaveRequestId,10L).quotaStatus).isEqualTo("CONSUMED");}
    @Test void pendingTerminateReleasesWhileApprovedTerminateRestoresConsumption(){LeaveRequest first=linked(save("pending-stop-001",13,"1"));assertThat(callbackService.apply(command(first,"TERMINATE","TERMINATED","pending-stop")).getAccepted()).isTrue();assertThat(units("reserved_units")).isZero();assertThat(units("consumed_units")).isZero();assertThat(jdbc.queryForObject("SELECT status FROM oa_attendance_leave_quota_allocation WHERE leave_request_id=?",String.class,first.leaveRequestId)).isEqualTo("RELEASED");LeaveRequest second=linked(save("approved-stop-001",14,"1"));callbackService.apply(command(second,"APPROVE","APPROVED","approved-first"));callbackService.apply(command(second,"TERMINATE","TERMINATED","approved-stop"));assertThat(units("consumed_units")).isZero();assertThat(jdbc.queryForObject("SELECT status FROM oa_attendance_leave_quota_allocation WHERE leave_request_id=?",String.class,second.leaveRequestId)).isEqualTo("REFUNDED");}
    @Test void callbackBusinessCasZeroRollsBackRealQuotaWrites(){LeaveRequest r=linked(save("cas-fail-001",13,"1"));OaAttendanceApprovalCallbackMapper fault=mock(OaAttendanceApprovalCallbackMapper.class,org.mockito.AdditionalAnswers.delegatesTo(callbacks));doReturn(0).when(fault).updateLeaveDecision(anyLong(),anyString(),anyLong(),anyString(),anyString(),any());var owner=proxy(new OaAttendanceApprovalCallbackService(fault,json,quota));long ledger=count("oa_attendance_leave_balance_ledger");assertThatThrownBy(()->owner.apply(command(r,"APPROVE","APPROVED","cas-zero"))).hasMessageContaining("CALLBACK_CONCURRENT_UPDATE");assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(units("consumed_units")).isZero();assertThat(count("oa_attendance_leave_balance_ledger")).isEqualTo(ledger);assertThat(count("oa_attendance_leave_quota_event")).isEqualTo(1);assertThat(leaveService.detail(r.leaveRequestId,10L).status).isEqualTo("PENDING");}
    @Test void outboxInsertFailureRollsBackAutomaticGrantReservationAndSubmitting(){LeaveRequest r=save("outbox-rollback-001",13,"1");jdbc.execute("CREATE TRIGGER b08c_fail_outbox BEFORE INSERT ON oa_attendance_leave_approval_start_outbox FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic outbox failure'");assertThatThrownBy(()->submit(r)).hasMessageContaining("synthetic outbox failure");assertThat(count("oa_attendance_leave_balance_bucket")).isZero();assertThat(count("oa_attendance_leave_quota_allocation")).isZero();assertThat(count("oa_attendance_leave_quota_event")).isZero();assertThat(count("oa_attendance_leave_balance_ledger")).isZero();assertThat(leaveService.detail(r.leaveRequestId,10L).status).isEqualTo("DRAFT");}
    @Test void unknownRemoteStartRetainsQuotaAndSameKeyRecovers(){LeaveRequest r=submit(save("unknown-start-001",13,"1"));Long id=outbox.selectByRound(r.leaveRequestId,1).outboxId;when(remote.start(any(),anyString())).thenReturn(null);dispatcher.dispatchOneNow(id);assertThat(leaveService.detail(r.leaveRequestId,10L).quotaStatus).isEqualTo("REVIEW");assertThat(units("reserved_units")).isEqualTo(420_000_000L);ApprovalStartResponse a=new ApprovalStartResponse();a.setInstanceId(900L);a.setBusinessRound(1);a.setStatus("RUNNING");when(remote.start(any(),anyString())).thenReturn(R.ok(a));dispatcher.dispatchOneNow(id);assertThat(leaveService.detail(r.leaveRequestId,10L).status).isEqualTo("PENDING");assertThat(count("oa_attendance_leave_quota_allocation")).isEqualTo(1);assertThat(units("reserved_units")).isEqualTo(420_000_000L);}
    @Test void firstInvalidOutboxSnapshotReturnsDraftAndReleasesAtomically(){LeaveRequest r=submit(save("never-started-001",13,"1"));Long id=outbox.selectByRound(r.leaveRequestId,1).outboxId;jdbc.update("UPDATE oa_attendance_leave_approval_start_outbox SET request_json='invalid' WHERE outbox_id=?",id);dispatcher.dispatchOneNow(id);LeaveRequest returned=leaveService.detail(r.leaveRequestId,10L);assertThat(returned.status).isEqualTo("RETURNED");assertThat(returned.quotaStatus).isEqualTo("RELEASED");assertThat(units("reserved_units")).isZero();verifyNoInteractions(remote);}
    @Test void expiredReleaseKeepsOriginalYearAndCannotCreateSpendableCredit(){LeaveRequest r=linked(save("expired-release-001",13,"1"));var laterQuota=new AttendanceLeaveQuotaService(quotas,leaves,mapper,service,credits,new AttendanceOvertimeTransferSourceGuard(transfers),json,Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));var laterCallback=proxy(new OaAttendanceApprovalCallbackService(callbacks,json,laterQuota));laterCallback.apply(command(r,"RETURN","RETURNED","expired-return"));assertThat(units("reserved_units")).isZero();assertThat(units("expired_units")).isEqualTo(420_000_000L);assertThat(jdbc.queryForObject("SELECT expires_on FROM oa_attendance_leave_balance_bucket",java.sql.Date.class).toLocalDate()).isEqualTo(LocalDate.of(2026,12,31));assertThat(jdbc.queryForObject("SELECT units FROM oa_attendance_leave_balance_ledger WHERE action='LEAVE_RELEASE'",Long.class)).isZero();}
    @Test void oldRoundCannotReleaseCurrentReservation(){LeaveRequest r=linked(save("old-round-001",13,"1"));var old=command(r,"REJECT","REJECTED","old-round");old.setBusinessRound(0);assertThat(callbackService.apply(old).getCode()).isEqualTo("STALE_APPROVAL_EVENT_IGNORED");assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_quota_event")).isEqualTo(1);}
    @Test void changedPolicyRejectsSavedDraftWithoutReinterpretingItsUnits(){LeaveRequest r=save("policy-drift-001",13,"1");jdbc.update("UPDATE oa_attendance_leave_type SET row_version=row_version+1 WHERE leave_type_id=1");assertThatThrownBy(()->submit(r)).hasMessageContaining("政策或单位已变化");assertThat(count("oa_attendance_leave_quota_allocation")).isZero();assertThat(leaveService.detail(r.leaveRequestId,10L).quotaUnits).isEqualTo(420_000_000L);}
    @Test void salaryCommittedWhileSubmitWaitsForMonthLockPreventsReservation()throws Exception{LeaveRequest r=save("salary-wait-001",13,"1");credits.ensurePeriodLock(10L,"2026-09");ExecutorService pool=Executors.newSingleThreadExecutor();try(Connection c=source.getConnection()){c.setAutoCommit(false);c.createStatement().executeQuery("SELECT 1 FROM oa_attendance_time_credit_period_lock WHERE shop_id=10 AND salary_month='2026-09' FOR UPDATE");Future<?> f=pool.submit(()->{employee();try{return submit(r);}finally{logout();}});assertThatThrownBy(()->f.get(180,TimeUnit.MILLISECONDS)).isInstanceOf(TimeoutException.class);c.createStatement().executeUpdate("INSERT INTO oa_salary_record(user_id,shop_dept_id,salary_month) VALUES(11,10,'2026-09')");c.commit();assertThatThrownBy(()->f.get(20,TimeUnit.SECONDS)).hasCauseInstanceOf(com.erp.common.core.exception.ServiceException.class);assertThat(count("oa_attendance_leave_quota_allocation")).isZero();}finally{pool.shutdownNow();}}
    @Test void salaryBoundaryPreventsRefundingApprovedLeave(){LeaveRequest r=linked(save("salary-refund-001",13,"1"));callbackService.apply(command(r,"APPROVE","APPROVED","approval-payroll"));jdbc.update("INSERT INTO oa_salary_record(user_id,shop_dept_id,salary_month) VALUES(11,10,'2026-09')");assertThatThrownBy(()->callbackService.apply(command(r,"TERMINATE","TERMINATED","invalid-refund"))).hasMessageContaining("已进入工资");assertThat(units("consumed_units")).isEqualTo(420_000_000L);assertThat(leaveService.detail(r.leaveRequestId,10L).status).isEqualTo("APPROVED");}
    @Test void quotaMigrationIsRepeatablePreservesPoliciesAndDoesNotGrantRoles()throws Exception{LeaveRequest r=save("migration-keeps-001",13,"1");long roleLinks=count("sys_role_menu");String policy=leaves.selectLeaveRequestById(r.leaveRequestId).quotaPolicyJson;migrateQuota();migrateQuota();assertThat(count("oa_attendance_leave_type")).isEqualTo(9);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oa_attendance_leave_type WHERE status='DISABLED'",Long.class)).isEqualTo(6);assertThat(count("sys_role_menu")).isEqualTo(roleLinks);assertThat(leaves.selectLeaveRequestById(r.leaveRequestId).quotaPolicyJson).isEqualTo(policy);assertThat(count("oa_attendance_leave_quota_allocation")).isZero();}

    Long configureCompensatory() {
        Long type=jdbc.queryForObject("SELECT leave_type_id FROM oa_attendance_leave_type WHERE type_code='COMPENSATORY'",Long.class);
        jdbc.update("UPDATE oa_attendance_leave_type SET unit_mode='MINUTE',pay_policy='PAID',balance_required=1,min_minutes=1,step_minutes=1,status='ENABLED' WHERE leave_type_id=?",type);
        login();try{RuleDraft draft=json.convertValue(AttendanceLeaveBalanceCalculatorTest.rule(),RuleDraft.class);draft.leaveTypeId=type;draft.config.leaveCategory="COMPENSATORY";draft.config.calculation="SOURCE_ONLY";draft.config.unit="MINUTES";draft.config.amount=BigDecimal.ZERO;draft.config.carryLimit=BigDecimal.ZERO;Rule r=service.saveRule(null,draft);service.publishRule(r.ruleId,0L);}finally{employee();}return type;
    }
    Transfer convert(Long type,String key,int minutes){login();try{var a=new AttendanceOvertimeTransferRequests.Apply();a.sourceDayResultId=1L;a.sourceVersion=1L;a.leaveTypeId=type;a.transferMinutes=minutes;a.clientRequestId=key;a.reason="synthetic settled source";return sourceService.apply(a,10L);}finally{employee();}}
    LeaveRequest compDraft(Long type,String key,int day,int minutes){var b=draft(key,day,null);b.leaveTypeId=type;b.endTime=b.startTime.plusMinutes(minutes);return leaveService.saveDraft(b,10L);}
    @Test void actualSettledOvertimeCanBeReservedAndConsumedButCannotThenBeReversed(){Long type=configureCompensatory();Transfer t=convert(type,"source-leave-001",80);LeaveRequest r=linked(compDraft(type,"comp-request-001",13,75));assertThat(units("reserved_units")).isEqualTo(75_000_000L);callbackService.apply(command(r,"APPROVE","APPROVED","comp-approved"));assertThat(units("consumed_units")).isEqualTo(75_000_000L);login();var rev=new AttendanceOvertimeTransferRequests.Reverse();rev.clientRequestId="spent-source-reverse";rev.reason="synthetic reversal";assertThatThrownBy(()->sourceService.reverse(t.transferId,rev,10L)).hasMessageContaining("原额度已占用、消耗");employee();assertThat(units("granted_units")).isEqualTo(80_000_000L);}
    @Test void invalidatedOvertimeCannotBeConsumedButUnusedReservationCanBeReleased(){Long type=configureCompensatory();convert(type,"source-invalid-001",80);LeaveRequest r=linked(compDraft(type,"comp-invalid-001",13,75));jdbc.update("UPDATE oa_attendance_day_result SET row_version=row_version+1,settled_at=NULL WHERE day_result_id=1");assertThatThrownBy(()->callbackService.apply(command(r,"APPROVE","APPROVED","invalid-approve"))).isInstanceOf(com.erp.common.core.exception.ServiceException.class);assertThat(units("reserved_units")).isEqualTo(75_000_000L);assertThat(units("consumed_units")).isZero();assertThat(callbackService.apply(command(r,"WITHDRAW","WITHDRAWN","invalid-withdraw")).getAccepted()).isTrue();assertThat(units("reserved_units")).isZero();assertThat(units("granted_units")).isEqualTo(80_000_000L);}
    @Test void leaveCannotInvalidateTheSettledDayAlreadyUsedForConversion(){Long type=configureCompensatory();convert(type,"source-same-day-001",80);LeaveRequest r=compDraft(type,"comp-same-day-001",10,75);assertThatThrownBy(()->submit(r)).hasMessageContaining("已用于抵扣或转休");assertThat(units("reserved_units")).isZero();assertThat(leaveService.detail(r.leaveRequestId,10L).status).isEqualTo("DRAFT");}

    void nightShift(boolean settled){
        jdbc.update("INSERT INTO oa_attendance_schedule(schedule_id,user_id,user_name,shop_id,business_date,shift_id,standard_minutes_snapshot,status,start_time_snapshot,end_time_snapshot,cross_day_snapshot) VALUES(50,11,'fixture',10,'2026-09-30',1,480,'PUBLISHED','22:00:00','06:00:00',1)");
        jdbc.update("INSERT INTO oa_attendance_schedule_segment_snapshot(schedule_id,segment_order,segment_type,start_minute_offset,end_minute_offset,paid) VALUES(50,1,'WORK',1320,1800,1)");
        if(settled)jdbc.update("INSERT INTO oa_attendance_day_result(day_result_id,schedule_id,user_id,user_name,shop_id,business_date,shift_id,scheduled_minutes,worked_minutes,paid_leave_minutes,unpaid_leave_minutes,absence_minutes,late_minutes,early_leave_minutes,result_status,settled_at,row_version) VALUES(50,50,11,'fixture',10,'2026-09-30',1,480,600,0,0,0,0,0,'NORMAL','2026-10-01 08:00:00',1)");
    }
    LeaveRequest nightDraft(String key){var b=draft(key,13,"1");b.startTime=LocalDateTime.of(2026,10,1,1,0);b.endTime=b.startTime.plusHours(1);return leaveService.saveDraft(b,10L);}
    @Test void crossMonthNightLeaveChecksActualPreviousPayrollMonth(){nightShift(true);LeaveRequest r=nightDraft("night-payroll-001");jdbc.update("INSERT INTO oa_salary_record(user_id,shop_dept_id,salary_month) VALUES(11,10,'2026-09')");assertThatThrownBy(()->submit(r)).hasMessageContaining("已进入工资");assertThat(units("reserved_units")).isZero();assertThat(jdbc.queryForObject("SELECT row_version FROM oa_attendance_day_result WHERE day_result_id=50",Long.class)).isEqualTo(1L);}
    @Test void crossMonthNightWithoutDayResultStillChecksPreviousPayrollMonth(){nightShift(false);LeaveRequest r=nightDraft("night-no-result-001");jdbc.update("INSERT INTO oa_salary_record(user_id,shop_dept_id,salary_month) VALUES(11,10,'2026-09')");assertThatThrownBy(()->submit(r)).hasMessageContaining("已进入工资");assertThat(count("oa_attendance_leave_quota_allocation")).isZero();}
