    @Test void migratedLegacyPendingRequestIsNotRetroactivelyCharged(){LeaveRequest created=save("legacy-history-001",13,"1");jdbc.update("UPDATE oa_attendance_leave_request SET quota_policy_json=NULL,quota_units=NULL,quota_status=NULL,requested_days=NULL,status='PENDING',business_round=1,approval_instance_id=999 WHERE leave_request_id=?",created.leaveRequestId);LeaveRequest legacy=leaveService.detail(created.leaveRequestId,10L);assertThat(legacy.quotaStatus).isEqualTo("LEGACY_NO_QUOTA");assertThat(callbackService.apply(command(legacy,"APPROVE","APPROVED","legacy-approval")).getAccepted()).isTrue();assertThat(count("oa_attendance_leave_quota_allocation")).isZero();assertThat(count("oa_attendance_leave_balance_bucket")).isZero();assertThat(leaveService.detail(created.leaveRequestId,10L).status).isEqualTo("APPROVED");}
    @Test void returnedDraftStartsANewRoundWithoutReusingReleasedAllocations(){LeaveRequest first=linked(save("return-round-001",13,"1"));callbackService.apply(command(first,"RETURN","RETURNED","return-round-one"));LeaveRequest returned=leaveService.detail(first.leaveRequestId,10L);var b=draft("unused-edit-key",13,"1");b.leaveRequestId=returned.leaveRequestId;b.rowVersion=returned.rowVersion;b.quotaPolicySnapshot=returned.quotaPolicySnapshot;LeaveRequest edited=leaveService.saveDraft(b,10L);LeaveRequest second=submit(edited);assertThat(second.businessRound).isEqualTo(2);assertThat(units("reserved_units")).isEqualTo(420_000_000L);assertThat(count("oa_attendance_leave_quota_allocation")).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT status FROM oa_attendance_leave_quota_allocation WHERE business_round=1",String.class)).isEqualTo("RELEASED");assertThat(jdbc.queryForObject("SELECT status FROM oa_attendance_leave_quota_allocation WHERE business_round=2",String.class)).isEqualTo("RESERVED");assertThat(callbackService.apply(command(first,"REJECT","REJECTED","stale-after-new-round")).getCode()).isEqualTo("STALE_APPROVAL_EVENT_IGNORED");assertThat(units("reserved_units")).isEqualTo(420_000_000L);}

    void changeRuleConversion(){login();try{RuleDraft next=json.convertValue(service.rule(ruleId),RuleDraft.class);next.previousRuleId=ruleId;next.config.minutesPerDay=new BigDecimal("480");Rule saved=service.saveRule(null,next);service.publishRule(saved.ruleId,0L);}finally{employee();}}
    AttendanceLeaveRequests.SaveDraft editBody(LeaveRequest r){var b=draft("preview-edit-key",13,"1");b.leaveRequestId=r.leaveRequestId;b.rowVersion=r.rowVersion;b.startTime=r.startTime;b.endTime=r.endTime;b.reason=r.reason;return b;}
    @Test void currentPolicyPreviewDoesNotWriteAndConfirmedSnapshotRecoversSameDraft(){LeaveRequest r=save("preview-recovery-001",13,"1");String original=leaves.selectLeaveRequestById(r.leaveRequestId).quotaPolicyJson;changeRuleConversion();var b=editBody(r);var p=leaveService.previewPolicy(r.leaveRequestId,b,10L);assertThat(p.quotaPolicySnapshot.ruleVersion).isEqualTo(2);assertThat(p.quotaUnits).isEqualTo(480_000_000L);assertThat(p.rowVersion).isEqualTo(r.rowVersion);assertThat(leaves.selectLeaveRequestById(r.leaveRequestId).quotaPolicyJson).isEqualTo(original);assertThat(count("oa_attendance_leave_balance_bucket")).isZero();assertThat(count("oa_attendance_leave_balance_ledger")).isZero();assertThat(count("oa_attendance_leave_balance_command")).isZero();assertThat(count("oa_attendance_leave_quota_allocation")).isZero();b.quotaPolicySnapshot=p.quotaPolicySnapshot;LeaveRequest edited=leaveService.saveDraft(b,10L);assertThat(edited.leaveRequestId).isEqualTo(r.leaveRequestId);assertThat(edited.quotaUnits).isEqualTo(480_000_000L);assertThat(submit(edited).quotaStatus).isEqualTo("RESERVED");assertThat(units("reserved_units")).isEqualTo(480_000_000L);}
    @Test void currentPolicyPreviewRejectsOtherOwnerAndStaleDraftWithoutWrites(){LeaveRequest r=save("preview-identity-001",13,"1");var b=editBody(r);login();assertThatThrownBy(()->leaveService.previewPolicy(r.leaveRequestId,b,10L)).hasMessageContaining("NOT_OWNED");employee();jdbc.update("UPDATE oa_attendance_leave_request SET row_version=row_version+1 WHERE leave_request_id=?",r.leaveRequestId);assertThatThrownBy(()->leaveService.previewPolicy(r.leaveRequestId,b,10L)).hasMessageContaining("VERSION");assertThat(count("oa_attendance_leave_balance_bucket")).isZero();assertThat(count("oa_attendance_leave_quota_allocation")).isZero();}
    @Test void policyChangedAfterPreviewStillRejectsSaveAndPreservesDraft(){LeaveRequest r=save("preview-race-001",13,"1");var b=editBody(r);var p=leaveService.previewPolicy(r.leaveRequestId,b,10L);changeRuleConversion();b.quotaPolicySnapshot=p.quotaPolicySnapshot;assertThatThrownBy(()->leaveService.saveDraft(b,10L)).hasMessageContaining("政策或单位已变化");assertThat(leaveService.detail(r.leaveRequestId,10L).quotaUnits).isEqualTo(420_000_000L);assertThat(leaveService.detail(r.leaveRequestId,10L).rowVersion).isEqualTo(r.rowVersion);assertThat(count("oa_attendance_leave_balance_bucket")).isZero();}
